#!/bin/sh
# Generates the Homebrew Formula for mcp-server-macos-use.
# Usage: scripts/generate-formula.sh <version> <sha256> [output_path]
set -eu

raw_version="${1:?usage: scripts/generate-formula.sh <version> <sha256> [output_path]}"
sha="${2:?usage: scripts/generate-formula.sh <version> <sha256> [output_path]}"
output="${3:-}"

version="${raw_version#v}"

render_formula() {
    cat <<EOF
# This file was generated by mcp-server-macos-use release automation. DO NOT EDIT.
class McpServerMacosUse < Formula
  desc "MCP server that lets AI agents control macOS apps through accessibility APIs"
  homepage "https://github.com/Diaszano/mcp-server-macos-use"
  url "https://github.com/Diaszano/mcp-server-macos-use/releases/download/v$version/mcp-server-macos-use-$version.tar.gz"
  sha256 "$sha"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  depends_on macos: :ventura

  def install
    # The server finds screenshot-helper next to argv[0], so both live in libexec behind an absolute-path wrapper.
    libexec.install "mcp-server-macos-use", "screenshot-helper"
    bin.write_exec_script libexec/"mcp-server-macos-use"
  end

  def caveats
    <<~TEXT
      Grant Accessibility and Screen Recording permissions to the app that launches
      the server (e.g. your terminal or MCP client) in System Settings > Privacy & Security.
    TEXT
  end

  test do
    assert_path_exists libexec/"screenshot-helper"
  end
end
EOF
}

if [ -n "$output" ]; then
    mkdir -p "$(dirname "$output")"
    render_formula > "$output"
else
    render_formula
fi
